      SUBROUTINE DEMEXCC     CALCULATES DERIVATIVES OF KNOWN MISALIGNMENT TRANSFORMATIONC     AT MAGNET EXITCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8D.CIN'      INCLUDE 'ELM8K.CIN'      INCLUDE 'ELM10B.CIN'       INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      REAL            DMM(3,3), DRM(3,3), DVDIS(3), DVROT(3), DVD1(3)      REAL            DVR1(3), XTEMP(3)C      EQUIVALENCE     (DX,VDIS(1)), (DY,VDIS(2)), (DZ,VDIS(3))      EQUIVALENCE     (RX,VROT(1)), (RY,VROT(2)), (RZ,VROT(3))      EQUIVALENCE     (DDX,DVDIS(1)), (DDY,DVDIS(2)), (DDZ,DVDIS(3))      EQUIVALENCE     (DRX,DVROT(1)), (DRY,DVROT(2)), (DRZ,DVROT(3))CC----------------------------------------------------------------------      DO 10 J = 1, 3      DVDIS(J) = 0.0      DVROT(J) = 0.0   10 CONTINUE      IF (JV .EQ. 1 .OR. JV .EQ. 3 .OR. JV .EQ. 5) THEN        JN = (JV + 1)/2        DVDIS(JN) = DPARM*UMIS(1)      ENDIF      IF (JV .EQ. 2 .OR. JV .EQ. 4 .OR. JV .EQ. 6) THEN        JN = JV/2        DVROT(JN) = DPARM*UMIS(2)      ENDIFC      DO 20 J = 1, 3      SD = 0.0      SR = 0.0      DO 18 K = 1, 3      SD = SD + OR(J,K)*DVDIS(K)      SR = SR + OR(J,K)*DVROT(K)   18 CONTINUE      DVD1(J) = SD      DVR1(J) = SR   20 CONTINUEC      DO 30 J = 1, 3      DVDIS(J) = DVD1(J)   30 DVROT(J) = DVR1(J)C      DTH = 0.0      IF (THMIS .NE. 0.0) DTH = RX*DRX + RY*DRY + RZ*DRZ      SN = SIN(THMIS)      CS = COS(THMIS)      ZN = SN**2/(1.0 + CS)      DSN = CS*DTH      DZN = SN*DTH      IF (THMIS .NE. 0.0) THEN        DRX = (DRX - RX*DTH)/THMIS        DRY = (DRY - RY*DTH)/THMIS        DRZ = (DRZ - RZ*DTH)/THMIS      ENDIFCC     ROTATION MATRIX FOR MAGNETC      DRM(1,1) = 2.0*RX*DRX*ZN - (1.0 - RX**2)*DZN      DRM(1,2) = - DRZ*SN - RZ*DSN + DRX*RY*ZN + RX*DRY*ZN + RX*RY*DZN      DRM(1,3) = DRY*SN + RY*DSN + DRX*RZ*ZN + RX*DRZ*ZN + RX*RZ*DZN      DRM(2,1) = DRZ*SN + RZ*DSN + DRX*RY*ZN + RX*DRY*ZN + RX*RY*DZN      DRM(2,2) = 2.0*RY*DRY*ZN - (1.0 - RY**2)*DZN      DRM(2,3) = - DRX*SN - RX*DSN + DRY*RZ*ZN + RY*DRZ*ZN + RY*RZ*DZN      DRM(3,1) = - DRY*SN - RY*DSN + DRX*RZ*ZN + RX*DRZ*ZN + RX*RZ*DZN      DRM(3,2) = DRX*SN + RX*DSN + DRY*RZ*ZN + RY*DRZ*ZN + RY*RZ*DZN      DRM(3,3) = 2.0*RZ*DRZ*ZN - (1.0 - RZ**2)*DZNC      DO 35 J = 1, 3      SS = 0.0      DO 32 K = 1, 3      SS = SS + OR(J,K)*XR(K)   32 CONTINUE      XTEMP(J) = SS   35 CONTINUEC      DO 40 J = 1, 3      SS = 0.0      DO 38 K = 1, 3      SS = SS + DRM(J,K)*XTEMP(K)   38 CONTINUE      DVDIS(J) = DVDIS(J) + SS   40 CONTINUEC      DMM(1,1) = (DRM(1,1) - DRM(1,3)*RM(3,1)/RM(3,3)     1  - DRM(3,1)*RM(1,3)/RM(3,3)     2  + DRM(3,3)*RM(1,3)*RM(3,1)/RM(3,3)**2)/RM(3,3)     3  - DRM(3,3)*(RM(1,1) - RM(1,3)*RM(3,1)/RM(3,3))/RM(3,3)**2      DMM(1,2) = (DRM(1,2) - DRM(1,3)*RM(3,2)/RM(3,3)     1  - DRM(3,2)*RM(1,3)/RM(3,3)     2  + DRM(3,3)*RM(1,3)*RM(3,2)/RM(3,3)**2)/RM(3,3)     3  - DRM(3,3)*(RM(1,2) - RM(1,3)*RM(3,1)/RM(3,3))/RM(3,3)**2      DMM(1,3) = DRM(1,3)/RM(3,3) - RM(1,3)*DRM(3,3)/RM(3,3)**2      DMM(2,1) = (DRM(2,1) - DRM(2,3)*RM(3,1)/RM(3,3)     1  - DRM(3,1)*RM(2,3)/RM(3,3)     2  + DRM(3,3)*RM(2,3)*RM(3,1)/RM(3,3)**2)/RM(3,3)     3  - DRM(3,3)*(RM(2,1) - RM(2,3)*RM(3,1)/RM(3,3))/RM(3,3)**2      DMM(2,2) = (DRM(2,2) - DRM(2,3)*RM(3,2)/RM(3,3)     1  - DRM(3,2)*RM(2,3)/RM(3,3)     2  + DRM(3,3)*RM(2,3)*RM(3,1)/RM(3,3)**2)/RM(3,3)     3  - DRM(3,3)*(RM(2,2) - RM(2,3)*RM(3,2)/RM(3,3))/RM(3,3)**2      DMM(2,3) = DRM(2,3)/RM(3,3) - RM(2,3)*DRM(3,3)/RM(3,3)**2C      CODV(1) = DDX - DMM(1,3)*DZ - MM(1,3)*DDZ      CODV(2) = DRM(1,3)/RM(3,3) - RM(1,3)*DRM(3,3)/RM(3,3)**2      CODV(3) = DDY - DMM(2,3)*DZ - MM(2,3)*DDZ      CODV(4) = DRM(2,3)/RM(3,3) - RM(2,3)*DRM(3,3)/RM(3,3)**2      CODV(5) = DDZ      DCOV = .TRUE.C      RV(1,1) = DRM(1,1) + DMM(1,3)*RM(3,1) + MM(1,3)*DRM(3,1)      RV(1,2) = - DMM(1,1)*DZ - MM(1,1)*DDZ      RV(1,3) = DRM(1,2) + DMM(1,3)*RM(3,2) + MM(1,3)*DRM(3,2)      RV(1,4) = - DMM(1,2)*DZ - MM(1,2)*DDZ      RV(2,2) = DMM(1,1)      RV(2,4) = DMM(1,2)      RV(3,1) = DRM(2,1) + DMM(2,3)*RM(3,1) + MM(2,3)*RM(3,1)      RV(3,2) = - DMM(2,1)*DZ - MM(2,1)*DDZ      RV(3,3) = DRM(2,2) + DMM(2,3)*RM(3,2) + MM(2,3)*DRM(3,2)      RV(3,4) = - DMM(2,2)*DZ - MM(2,2)*DDZ      RV(4,2) = DMM(2,1)      RV(4,4) = DMM(2,2)C      DO 75 J = 1, 3      VD = 0.0      DO 70 K = 1, 3      VD = VD + RM(K,J)*DVDIS(K)   70 CONTINUE      DVD1(J) = - VD   75 CONTINUEC      DO 80 J = 1, 3      X0V(1,J) = DVD1(J)      DO 80 K = 1, 3      OV(1,J,K) = DRM(J,K)   80 CONTINUE      RETURN      END